// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 wei so Collect is allowed
        c.SetMinSum(1);
        // Alice and Bob addresses
        address alice = address(0x1111);
        address bob = address(0x2222);

        // Fund Alice with 5 ether and deposit
        vm.deal(alice, 5 ether);
        vm.prank(alice);
        c.Deposit{value: 5 ether}();

        // Fund Bob with 1 ether and deposit
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.Deposit{value: 1 ether}();

        // Alice collects 3 ether
        vm.prank(alice);
        c.Collect(3 ether);

        // Assert: reference contract sets Alice's balance to 2 ether
        // (buggy contract would leave it at 5 ether)
        assertTrue(c.balances(alice) == 2 ether, "Alice balance should be 2 ether");
    }
}

